<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue'; import MTabs from '../../components/mds/MTabs.vue'; import { HostSurface } from '../../platform/host-adapter.mjs'; import { createReportsApi, dateRange } from './domain/reports-api.mjs'; import { careAlertsViewModel, reportRowsViewModel, reportsOverviewViewModel } from './domain/reports-view.mjs'; import { budgetsViewModel } from './domain/budget-write.mjs'; import ReportsOverviewDesktop from './desktop/ReportsOverviewDesktop.vue'; import ReportsOverviewMobile from './mobile/ReportsOverviewMobile.vue'; import ReportsDetailDesktop from './desktop/ReportsDetailDesktop.vue'; import ReportsDetailMobile from './mobile/ReportsDetailMobile.vue'; import BudgetsDesktop from './desktop/BudgetsDesktop.vue'; import BudgetsMobile from './mobile/BudgetsMobile.vue';
const props=defineProps({surface:String,adapter:Object,hostUnavailable:Boolean});const emit=defineEmits(['back']);const api=createReportsApi();const isNative=computed(()=>props.surface===HostSurface.NATIVE);const safeArea=ref(props.adapter?.getSafeArea?.()||{});const safeAreaStyle=computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap((side)=>Number.isFinite(Number(safeArea.value?.[side]))?[[`--mds-mobile-safe-${side}`,`${Number(safeArea.value[side])}px`]]:[])));const tabs=Object.freeze([{key:'overview',label:'Tổng quan'},{key:'staff',label:'Nhân sự'},{key:'unit',label:'Đơn vị'},{key:'awards',label:'Giải thưởng'},{key:'alerts',label:'Cảnh báo'},{key:'budgets',label:'Ngân sách'}]);const reportSpec=Object.freeze({staff:{title:'Hiệu quả theo nhân sự',description:'Số liệu do máy chủ tổng hợp trong kỳ đang chọn.',columns:[{key:'full_name',label:'Nhân sự'},{key:'assigned',label:'Đầu mối'},{key:'interactions',label:'Tương tác'},{key:'spend',label:'Chi booking',money:true},{key:'overdue',label:'Quá hạn'}]},unit:{title:'Tình hình theo đơn vị',description:'Dữ liệu được chiếu theo quyền hiện tại.',columns:[{key:'name',label:'Đơn vị'},{key:'people_cnt',label:'Nhân sự'},{key:'inter_cnt',label:'Tương tác'},{key:'book_cnt',label:'Booking'},{key:'spend',label:'Chi',money:true}]},awards:{title:'Chi phí giải thưởng',description:'Tổng chi được máy chủ tính; UI không tự cộng tiền.',columns:[{key:'name',label:'Giải thưởng'},{key:'organizer',label:'Đơn vị tổ chức'},{key:'status',label:'Trạng thái'},{key:'totalCost',label:'Tổng chi',money:true}]},alerts:{title:'Cảnh báo chăm sóc',description:'Đầu mối cần được ưu tiên tương tác lại.',columns:[{key:'name',label:'Đối tượng'},{key:'sub',label:'Phân loại'},{key:'days',label:'Số ngày'},{key:'bucket',label:'Mức cảnh báo'}]}});const state=reactive({phase:'loading',range:{...dateRange('month'),kind:'month'},overview:null,active:'overview',detailRows:[],detailLoading:false,budgetRows:[],budgetSaving:false,budgetError:'',currentUser:null,error:null});const canManageBudgets=computed(()=>['admin','super_admin'].includes(state.currentUser?.role));
async function load(kind=state.range.kind){if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.'};return;}state.range={...dateRange(kind),kind};state.phase='loading';state.error=null;try{const [overview,session]=await Promise.all([api.getOverview(state.range),api.getCurrentUser()]);state.overview=reportsOverviewViewModel(overview);state.currentUser=session?.user||null;state.phase='ready';if(state.active!=='overview')await loadDetail(state.active);}catch(error){state.phase='error';state.error=error;}}
async function loadDetail(key){state.active=key;if(key==='overview')return;state.detailLoading=true;state.error=null;try{if(key==='budgets'){state.budgetRows=budgetsViewModel(await api.getBudgets());return;}let rows;if(key==='staff')rows=reportRowsViewModel(await api.getByStaff(state.range));else if(key==='unit')rows=reportRowsViewModel(await api.getByUnit(state.range));else if(key==='awards')rows=reportRowsViewModel(await api.getAwards(state.range));else rows=careAlertsViewModel(await api.getCareAlerts()).rows;state.detailRows=rows;}catch(error){state.error=error;state.detailRows=[];state.budgetRows=[];}finally{state.detailLoading=false;}}
async function saveBudget(input){if(!canManageBudgets.value)return;state.budgetSaving=true;state.budgetError='';try{await api.saveBudget(input);await loadDetail('budgets');state.overview=reportsOverviewViewModel(await api.getOverview(state.range));}catch(error){state.budgetError=error.message;}finally{state.budgetSaving=false;}}
function back(){if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'reports-overview'});emit('back');}onMounted(load);
</script>
<template><div v-if="state.phase==='loading'" :class="isNative?'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]':'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28"/></div><section v-else-if="state.phase==='error'" :class="isNative?'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]':'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Báo cáo" @back="back"/><MEmptyState :title="state.error.status===403?'Bạn không có quyền xem báo cáo':'Không thể mở báo cáo'" :description="state.error.message"/></section><template v-else><BudgetsMobile v-if="isNative&&state.active==='budgets'" :rows="state.budgetRows" :can-manage="canManageBudgets" :saving="state.budgetSaving" :error="state.budgetError" :safe-area-style="safeAreaStyle" @back="state.active='overview'" @save="saveBudget" @save-error="state.budgetError=$event"/><ReportsDetailMobile v-else-if="isNative&&state.active!=='overview'" v-bind="reportSpec[state.active]" :rows="state.detailRows" :safe-area-style="safeAreaStyle" @back="state.active='overview'"/><ReportsOverviewMobile v-else-if="isNative" :overview="state.overview" :range="state.range" :loading="state.phase==='loading'" :tabs="tabs" :active="state.active" :safe-area-style="safeAreaStyle" @back="back" @range="load" @tab="loadDetail"/><section v-else class="min-h-0 bg-[var(--mds-bg-page)]"><MTabs v-model="state.active" :tabs="tabs" class="bg-[var(--mds-bg)] px-4" @update:model-value="loadDetail"/><BudgetsDesktop v-if="state.active==='budgets'" :rows="state.budgetRows" :can-manage="canManageBudgets" :saving="state.budgetSaving" :error="state.budgetError" @save="saveBudget" @save-error="state.budgetError=$event"/><ReportsDetailDesktop v-else-if="state.active!=='overview'" v-bind="reportSpec[state.active]" :rows="state.detailRows" :loading="state.detailLoading"/><ReportsOverviewDesktop v-else :overview="state.overview" :range="state.range" :loading="state.phase==='loading'" @range="load"/></section></template></template>
